/**
 * The block / mark / document types: the block id, the doc meta, the JSON
 * document shape, the per-block attrs, and the block interfaces. The inline
 * text types (the mark set, the runs) stand in text; the table block types
 * stand in table.
 */
import type { Block } from "./block-union";
import type { BlockContent, TextRun } from "./text";

/** Block identifier (nanoid, generated by the change author; never reused). */
type BlockId = string;

type TextAlign = "left" | "center" | "right";

/** Document metadata. */
interface DocMeta {
  /** Schema version. */
  v: 1;
  /** Document identifier (nanoid). */
  id: string;
  /** Document title (empty string is a valid state). */
  title: string;
  /** The page avatar (a short string / a few emoji; absent or empty = none). */
  avatar?: string;
  /** Creation time, ISO 8601. */
  createdAt: string;
}

/**
 * An opaque block snapshot: a block of an unknown type (a future minor's
 * data) preserved as-is. The reader/renderer stand a placeholder (and the
 * text without the unknown marks); the data is not lost on save (the writer's
 * opaque stand). The strict validator rejects it (the writer's contract — a
 * v1 writer never emits it).
 *
 * The `type` is a plain string (a name outside the v1 registry): a
 * `block.type === "<known>"` check narrows away the other known members but
 * keeps this one (the type is unknown), so a specific known type is accessed
 * through a narrowed cast after the check.
 */
interface OpaqueBlock {
  /** The unknown block type (a name outside the v1 registry). */
  type: string;
  attrs?: Record<string, unknown>;
  content?: TextRun[];
  children?: BlockId[];
  geometry?: Record<string, number>;
}

/** Document in the public JSON format. */
interface DocJSON extends DocMeta {
  /** Flat map: block id -> block. Order lives in `children`. An unknown-type block (a future minor's data) stands as the opaque entry. */
  blocks: Record<BlockId, Block | OpaqueBlock>;
}

/** The flat-page nesting depth of a page block relative to the preceding block of the same sequence (default 0). */
type PageIndent = number;

interface HeadingAttrs {
  /** Heading level 1-6. */
  level: 1 | 2 | 3 | 4 | 5 | 6;
  align?: TextAlign;
  /** Nesting depth in the page sequence (default 0). */
  indent?: PageIndent;
}

interface ListItemAttrs {
  list: "bullet" | "number" | "task";
  checked?: boolean;
  align?: TextAlign;
  /** Nesting depth in the page sequence (default 0). */
  indent?: PageIndent;
}

interface ParagraphAttrs {
  align?: TextAlign;
  /** Nesting depth in the page sequence (default 0). */
  indent?: PageIndent;
}

interface CalloutAttrs {
  variant?: "info" | "warning" | "danger";
  /** The color override (a hex); absent or `null` = the preset color per
   *  `variant` (the null idiom — attrs are never removed). */
  color?: string | null;
  /** The icon override (a name from the callout's icon catalog); absent or
   *  `null` = the preset icon per `variant`. */
  icon?: string | null;
  align?: TextAlign;
  /** Nesting depth in the page sequence (default 0). */
  indent?: PageIndent;
}

interface QuoteAttrs {
  align?: TextAlign;
  /** Nesting depth in the page sequence (default 0). */
  indent?: PageIndent;
}

interface CodeAttrs {
  language?: string;
  /** The five-line collapsed view (default false). */
  collapsed?: boolean;
  /** The caption line below the block; the empty string means no caption (attrs are never removed). */
  caption?: string;
  /** The line-number column (default true). */
  lineNumbers?: boolean;
  /** Wrap at the container width instead of horizontal scroll (default true). */
  wrap?: boolean;
  /** The mermaid view mode (default "code"). */
  mermaidMode?: "code" | "preview";
  /** Nesting depth in the page sequence (default 0). */
  indent?: PageIndent;
}

interface TableCellAttrs {
  /** The column this cell belongs to (a `columnOrder` entry). Set automatically by the insert path (the cell's position in the row's columnOrder). */
  columnId?: string;
  align?: TextAlign;
  /** The column background color (hex); the display priority layer over the row color. */
  columnColor?: string;
  /** The row background color (hex); stands under the column color. */
  rowColor?: string;
}

interface ImageAttrs {
  /** Opaque blob key (resolved by the consumer). */
  src: string;
  /** The display width in px (the aspect ratio stands — the height
   *  follows); absent or `null` = the editor's full width. The renderer
   *  never draws the figure wider than the editor. */
  width?: number | null;
  /** The figure's horizontal placement at a reduced width ("left" is the
   *  absent attr). */
  align?: TextAlign;
  /** The caption line below the figure (the code block's caption idiom;
   *  the empty string is the removed state). */
  caption?: string;
  /** Nesting depth in the page sequence (default 0). */
  indent?: PageIndent;
}

interface EmbedAttrs {
  /** Embed kind; a renderer hint (all kinds render as an iframe in v1). */
  kind: "iframe" | "github" | "figma" | "loom" | "html";
  /** The embedded page URL. */
  src: string;
  /** Accessible title; falls back to the kind in the renderer. */
  title?: string;
  /** Nesting depth in the page sequence (default 0). */
  indent?: PageIndent;
}

interface RootBlock {
  type: "root";
  /** Top-level page blocks, in reading order. */
  children: BlockId[];
}

interface ParagraphBlock {
  type: "paragraph";
  attrs?: ParagraphAttrs;
  content?: BlockContent;
  /** LEGACY nesting form (readable v1): normalized to `indent` on load; the writer never emits it. */
  children?: BlockId[];
}

interface HeadingBlock {
  type: "heading";
  attrs: HeadingAttrs;
  content?: BlockContent;
  /** LEGACY nesting form (readable v1): normalized to `indent` on load; the writer never emits it. */
  children?: BlockId[];
}

interface ListItemBlock {
  type: "list-item";
  attrs: ListItemAttrs;
  content?: BlockContent;
  /** LEGACY nesting form (readable v1): nested `list-item` blocks only; normalized to `indent` on load. */
  children?: BlockId[];
}

interface CalloutBlock {
  type: "callout";
  attrs?: CalloutAttrs;
  content?: BlockContent;
  /** LEGACY nesting form (readable v1): normalized to `indent` on load; the writer never emits it. */
  children?: BlockId[];
}

interface QuoteBlock {
  type: "quote";
  attrs?: QuoteAttrs;
  content?: BlockContent;
  /** LEGACY nesting form (readable v1): normalized to `indent` on load; the writer never emits it. */
  children?: BlockId[];
}

interface CodeBlock {
  type: "code";
  attrs?: CodeAttrs;
  content?: BlockContent;
  /** LEGACY nesting form (readable v1): normalized to `indent` on load; the writer never emits it. */
  children?: BlockId[];
}

interface ImageBlock {
  type: "image";
  attrs: ImageAttrs;
}

interface EmbedBlock {
  type: "embed";
  attrs: EmbedAttrs;
}

/**
 * A sync-embed reference: the master document, optionally narrowed to a
 * block subtree inside it (the subtree's entry list renders).
 */
interface SyncEmbedRef {
  /** The master document id; the consumer resolves the doc from their own store. */
  docId: string;
  /** A subtree root block of the master; absent — the whole master document. */
  blockId?: string;
}

interface SyncEmbedAttrs {
  /** The reference to the master document. */
  ref: SyncEmbedRef;
  /** Nesting depth in the page sequence (default 0). */
  indent?: PageIndent;
}

interface SyncEmbedBlock {
  type: "sync-embed";
  attrs: SyncEmbedAttrs;
}

interface DividerAttrs {
  /** Nesting depth in the page sequence (default 0). */
  indent?: PageIndent;
}

interface DividerBlock {
  type: "divider";
  attrs?: DividerAttrs;
}

export type {
  BlockId,
  CalloutAttrs,
  CalloutBlock,
  CodeAttrs,
  CodeBlock,
  DocJSON,
  DocMeta,
  DividerAttrs,
  DividerBlock,
  EmbedAttrs,
  EmbedBlock,
  HeadingAttrs,
  HeadingBlock,
  ImageAttrs,
  ImageBlock,
  ListItemAttrs,
  ListItemBlock,
  OpaqueBlock,
  PageIndent,
  ParagraphAttrs,
  ParagraphBlock,
  QuoteAttrs,
  QuoteBlock,
  RootBlock,
  TableCellAttrs,
  TextAlign,
  SyncEmbedAttrs,
  SyncEmbedBlock,
  SyncEmbedRef,
};

export type {
  CanvasRef,
  CanvasTextAttrs,
  CanvasTextBlock,
  ConnectorAttrs,
  ConnectorBlock,
  FrameBlock,
  Geometry,
  ShapeAttrs,
  ShapeBlock,
  SurfaceAttrs,
  SurfaceBlock,
  WithGeometry,
} from "./canvas";
export type {
  DatabaseAttrs,
  DatabaseBlock,
  DatabaseCellType,
  DatabaseCellValue,
  DatabaseColumn,
  DatabaseFilterCondition,
  DatabaseFilterPayload,
  DatabaseSavedView,
} from "./database";
